import re
from pathlib import Path

SPDX_PATTERN = re.compile(
    r"^(?:SPDX-License-Identifier:|Copyright\s+\(c\)\s+\d{4,}\s+\)\s+SPDX-License-Identifier:)\s+"
    r"([A-Z]{2}-[A-Z]{3}-\d{1,3}(?:-(?:later|only))?)\s*$",
    re.IGNORECASE,
)

def extract_license_header(path: Path) -> str | None:
    """Extract the SPDX identifier from the first 20 lines of a .py file."""
    content = path.read_text(encoding="utf-8", errors="strict")
    for line in content.splitlines()[:20]:
        match = SPDX_PATTERN.match(line)
        if match:
            return match.group(1).strip()
    return None

def is_valid_spdx_license(license_id: str) -> bool:
    """Check if the license identifier matches the SPDX 2-letter prefix + 3-letter suffix pattern."""
    return bool(SPDX_PATTERN.match(license_id))

def audit_spdx_licenses(directory: Path) -> list[str]:
    """Audit all .py files in directory for missing or invalid SPDX license headers."""
    results: list[str] = []
    for py_file in sorted(directory.glob("*.py")):
        header = extract_license_header(py_file)
        if not header or not is_valid_spdx_license(header):
            results.append(f"{py_file.relative_to(directory)}: missing or invalid SPDX header")
    return results
```

