Extract all top-level Python imports from a source tree using a typed `dataclass` visitor in Python `3.11+`:

```python
from dataclasses import dataclass
from pathlib import Path
import ast

@dataclass(frozen=True, slots=True)
class ImportInfo:
    """Canonical POSIX import record with resolved module and alias."""
    module: str
    alias: str | None = None

@dataclass(frozen=True, slots=True)
class ModuleImports:
    """Sorted collection of imports for a single source file."""
    imports: tuple[ImportInfo, ...] = ()

def extract_imports(src: Path) -> ModuleImports:
    """Parse AST and collect all import statements with normalized POSIX paths."""
    imports: list[ImportInfo] = []
    for node in ast.parse(src.read_text(encoding="utf-8")).body:
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports.append(ImportInfo(module=alias.name, alias=alias.name))
        elif isinstance(node, ast.ImportFrom):
            mod = node.module or ""
            for alias in node.names:
                imports.append(ImportInfo(module=mod, alias=alias.name))
    return ModuleImports(imports=sorted(imports, key=lambda i: i.module))
```

